import{_ as r,o as a,c as e,ag as s}from"./chunks/framework.DB9Ll7VW.js";const g=JSON.parse('{"title":"Your WordPress admin (Sikshya)","description":"A simple map of the Sikshya sidebar in WordPress—what each section is for and where to learn more. No code required.","frontmatter":{"title":"Your WordPress admin (Sikshya)","description":"A simple map of the Sikshya sidebar in WordPress—what each section is for and where to learn more. No code required.","prev":{"text":"Quick start","link":"/quick-start"},"next":{"text":"Courses & curriculum","link":"/courses"}},"headers":[],"relativePath":"admin-dashboard.md","filePath":"admin-dashboard.md","lastUpdated":1778327862000}'),o={name:"admin-dashboard.md"};function n(i,t,d,h,l,c){return a(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="your-wordpress-admin-sikshya" tabindex="-1">Your WordPress admin (Sikshya) <a class="header-anchor" href="#your-wordpress-admin-sikshya" aria-label="Permalink to &quot;Your WordPress admin (Sikshya)&quot;">​</a></h1><p>Open <strong>WordPress admin → Sikshya</strong> (your site may show a custom name from branding). You get one full-screen app with a <strong>sidebar</strong>. The labels below match what the plugin ships in code—if you don’t see an item, your <strong>user role</strong> may not have access (students don’t see most of this).</p><blockquote><p><strong>Free vs Pro:</strong> Some links show a small <strong>Upgrade</strong> or <strong>Off</strong> badge in the sidebar (same colors as in the product). That means the feature needs <strong>Sikshya Pro</strong>, the right <strong>plan</strong>, and the <strong>Add-on</strong> switched on under <strong>Addons</strong>.</p></blockquote><h2 id="sidebar-groups-simple-map" tabindex="-1">Sidebar groups (simple map) <a class="header-anchor" href="#sidebar-groups-simple-map" aria-label="Permalink to &quot;Sidebar groups (simple map)&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><p>Your home inside Sikshya—stats and shortcuts. Start here after <a href="/docs/quick-start">Quick start</a>.</p><h3 id="course-group" tabindex="-1">Course (group) <a class="header-anchor" href="#course-group" aria-label="Permalink to &quot;Course (group)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>What it’s for</th><th>Documentation</th></tr></thead><tbody><tr><td><strong>Courses</strong></td><td>List and open the course builder</td><td><a href="/docs/courses">Courses &amp; curriculum</a></td></tr><tr><td><strong>Categories</strong></td><td>Course categories</td><td><a href="/docs/courses">Courses &amp; curriculum</a></td></tr><tr><td><strong>Content library</strong></td><td>Lessons, quizzes, assignments, chapters, questions in one place</td><td><a href="/docs/courses">Courses &amp; curriculum</a></td></tr><tr><td><strong>Learning rules</strong></td><td>Drip &amp; prerequisites <strong>Pro</strong></td><td><a href="/docs/enrollment-settings">Enrollment &amp; access</a>, <a href="/docs/third-party-integrations">Pro add-ons</a></td></tr><tr><td><strong>Reviews</strong></td><td>Course reviews <strong>Pro</strong></td><td><a href="/docs/third-party-integrations">Pro add-ons</a></td></tr><tr><td><strong>Discussions &amp; Q&amp;A</strong></td><td>In-course Q&amp;A <strong>Pro</strong></td><td><a href="/docs/third-party-integrations">Pro add-ons</a></td></tr><tr><td><strong>Course staff</strong></td><td>Multi-instructor <strong>Pro</strong></td><td><a href="/docs/third-party-integrations">Pro add-ons</a></td></tr></tbody></table><h3 id="people-group" tabindex="-1">People (group) <a class="header-anchor" href="#people-group" aria-label="Permalink to &quot;People (group)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>What it’s for</th><th>Documentation</th></tr></thead><tbody><tr><td><strong>Students &amp; Instructors</strong></td><td>User management for your academy</td><td><a href="/docs/learners">Learners, roles &amp; progress</a></td></tr><tr><td><strong>Enrollments</strong></td><td>Who is in which course</td><td><a href="/docs/enrollment-settings">Enrollment &amp; access</a></td></tr></tbody></table><h3 id="certificates" tabindex="-1">Certificates <a class="header-anchor" href="#certificates" aria-label="Permalink to &quot;Certificates&quot;">​</a></h3><p>Templates and issued certificates together. See <a href="/docs/courses">Courses &amp; curriculum</a> and <a href="/docs/third-party-integrations">Pro add-ons</a> for the advanced certificate builder.</p><h3 id="grading-submissions-group" tabindex="-1">Grading &amp; submissions (group) <a class="header-anchor" href="#grading-submissions-group" aria-label="Permalink to &quot;Grading &amp; submissions (group)&quot;">​</a></h3><p>Assignment marking and <strong>Gradebook</strong> (<strong>Pro</strong>). See <a href="/docs/third-party-integrations">Pro add-ons</a>.</p><h3 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h3><p>High-level reports. See <a href="/docs/learners">Learners</a> and <a href="/docs/third-party-integrations">Pro add-ons</a> for advanced exports.</p><h3 id="commerce-group" tabindex="-1">Commerce (group) <a class="header-anchor" href="#commerce-group" aria-label="Permalink to &quot;Commerce (group)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Sales</strong></td><td>Orders and payments together</td></tr><tr><td><strong>Coupons</strong></td><td>Discount codes (free core; <strong>advanced rules</strong> are Pro)</td></tr><tr><td><strong>Subscriptions</strong></td><td><strong>Pro</strong> add-on</td></tr><tr><td><strong>Marketplace</strong></td><td><strong>Pro</strong> (Scale tier)</td></tr></tbody></table><p>Details: <a href="/docs/payment-settings">Payments</a>, <a href="/docs/enrollment-settings">Enrollment &amp; access</a>.</p><h3 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h3><p>Webhooks, API keys, and related automation (<strong>Pro / Scale</strong>). <a href="/docs/third-party-integrations">Pro add-ons</a>.</p><h3 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h3><p>Email delivery settings and templates. <a href="/docs/email-settings">Email &amp; notifications</a>.</p><h3 id="branding" tabindex="-1">Branding <a class="header-anchor" href="#branding" aria-label="Permalink to &quot;Branding&quot;">​</a></h3><p>Logos, colors, and labels (<strong>Pro</strong> options may apply). <a href="/docs/third-party-integrations">Pro add-ons</a>.</p><h3 id="addons" tabindex="-1">Addons <a class="header-anchor" href="#addons" aria-label="Permalink to &quot;Addons&quot;">​</a></h3><p>Turn <strong>Pro</strong> features on or off per site. <a href="/docs/third-party-integrations">Pro add-ons</a>.</p><h3 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h3><p>Paste and activate <strong>Sikshya Pro</strong>. <a href="/docs/installation">Installation</a>.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>All the tabs built in Settings (general, courses, payments, email, permalinks, …). Use <a href="/docs/payment-settings">Payments</a>, <a href="/docs/email-settings">Email</a>, and <a href="/docs/enrollment-settings">Enrollment &amp; access</a> for the chapters that match what you’re changing.</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Sample data import and maintenance. <a href="/docs/quick-start">Quick start</a>.</p><blockquote><p><strong>Setup Wizard</strong> stays registered under Sikshya for access checks, but the <strong>submenu link is hidden</strong>—the wizard still appears when the plugin prompts you after activation.</p></blockquote><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><ul><li>New site: <a href="/docs/quick-start">Quick start</a>, then <strong>Courses → Add</strong>.</li><li>Selling: <a href="/docs/payment-settings">Payments</a>.</li><li>Upgrading: <a href="https://mantrabrain.com/plugins/sikshya/#pricing" target="_blank" rel="noreferrer">Get Sikshya Pro</a>.</li></ul>',36)])])}const p=r(o,[["render",n]]);export{g as __pageData,p as default};
